//! The tables of a service, created from its design.
//!
//! @generated by service-builder. Do not edit: changes are overwritten on the next export.

use anyhow::{Context, Result};
use sqlx::PgPool;

const LOCK_SCHEMA: i64 = 0x6f62_7873;

/// Runs the statements of the design in one transaction. They are idempotent
/// (`CREATE TABLE IF NOT EXISTS`, `ADD COLUMN IF NOT EXISTS`), so this is safe on every start-up and
/// from several replicas at once. Changes that lose data (dropping or renaming a column) are not made.
pub async fn apply_schema(pool: &PgPool, statements: &[&str]) -> Result<()> {
    let mut tx = pool.begin().await?;
    sqlx::query("SELECT pg_advisory_xact_lock($1)")
        .bind(LOCK_SCHEMA)
        .execute(&mut *tx)
        .await?;
    for statement in statements {
        sqlx::query(statement)
            .execute(&mut *tx)
            .await
            .with_context(|| format!("cannot apply: {statement}"))?;
    }
    tx.commit().await?;
    Ok(())
}
